public Task InvokeAsync(HttpContext context) {
var watch = new Stopwatch();
watch.Start();
context.Response.OnStarting(() => {
watch.Stop();
var responseTimeForCompleteRequest =
watch.ElapsedMilliseconds;
context.Response.Headers[X_RESPONSE_TIME_MS] =
